public class Query
{
    [Query]
    [UseCache(MaxAge = 300)] // 5 minutes
    public async Task<Book?> GetBookAsync(int id, [Service] AppDbContext db)
    {
        return await db.Books.FindAsync(id);
    }
}

[Query]
[UseQueryCache(MaxAge = 60)]
public async Task<BookStats> GetStatsAsync([Service] AppDbContext db)
{
    return new BookStats
    {
        TotalBooks = await db.Books.CountAsync(),
        AveragePrice = await db.Books.AverageAsync(b => b.Price)
    };
}
